import { MakeLogicType, afterMount, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { signalsTrialCreate, signalsTrialList } from 'products/signals/frontend/generated/api'
import type { SelfDrivingTrialStatusApi } from 'products/signals/frontend/generated/api.schemas'

import { scoutFleetLogic } from './scoutFleetLogic'

export interface SelfDrivingTrialLogicProps {
    teamId: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface selfDrivingTrialLogicValues {
    error: string | null
    trial: SelfDrivingTrialStatusApi | null
    trialLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface selfDrivingTrialLogicActions {
    activateTrial: () => any
    activateTrialFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    activateTrialSuccess: (
        trial: SelfDrivingTrialStatusApi,
        payload?: any
    ) => {
        trial: SelfDrivingTrialStatusApi
        payload?: any
    }
    loadTrial: () => any
    loadTrialFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadTrialSuccess: (
        trial: SelfDrivingTrialStatusApi,
        payload?: any
    ) => {
        trial: SelfDrivingTrialStatusApi
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface selfDrivingTrialLogicMeta {
    key: number
}

export type selfDrivingTrialLogicType = MakeLogicType<
    selfDrivingTrialLogicValues,
    selfDrivingTrialLogicActions,
    SelfDrivingTrialLogicProps,
    selfDrivingTrialLogicMeta
>

export const selfDrivingTrialLogic = kea<selfDrivingTrialLogicType>([
    props({} as SelfDrivingTrialLogicProps),
    key(({ teamId }) => teamId),
    path((key) => ['products', 'signals', 'selfDrivingTrialLogic', key]),
    loaders(({ props }) => ({
        trial: [
            null as SelfDrivingTrialStatusApi | null,
            {
                loadTrial: async (): Promise<SelfDrivingTrialStatusApi> => signalsTrialList(String(props.teamId)),
                activateTrial: async (): Promise<SelfDrivingTrialStatusApi> => signalsTrialCreate(String(props.teamId)),
            },
        ],
    })),
    reducers({
        error: [
            null as string | null,
            {
                loadTrial: () => null,
                activateTrial: () => null,
                loadTrialFailure: () => 'Could not load trial status. Try again.',
                activateTrialFailure: () => 'Could not finish activating your trial. Retry to check its status.',
            },
        ],
    }),
    listeners({
        activateTrialSuccess: () => scoutFleetLogic.findMounted()?.actions.loadScoutConfigs(),
    }),
    afterMount(({ actions, values, cache }) => {
        actions.loadTrial()
        cache.disposables.add(() => {
            const timer = window.setInterval(() => {
                if (!values.trialLoading) {
                    actions.loadTrial()
                }
            }, 60_000)
            return () => window.clearInterval(timer)
        })
    }),
])
